import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 소유 대상 유형 값 '게시글'로 첨부파일을 찾는다 (BEHAVIOR.md 값의 출처)
const ATTACHMENT_OWNER_TYPE = '게시글';

@Controller('api/v1')
export class FnSfr04004Controller {
  @Get('/posts/:postId')
  async getPost(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const postId = req.params['postId'];
    if (typeof postId !== 'string' || !/^[0-9]+$/.test(postId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '게시글 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const posts = await db.query(
        'SELECT p.post_id AS "postId", p.title AS "title", p.author_id AS "authorId", p.content AS "content", p.visibility_scope AS "visibilityScope", a.department_id AS "authorDepartmentId" FROM post p JOIN employee a ON a.employee_id = p.author_id WHERE p.post_id = CAST(:postId AS bigint)',
        { postId },
      );
      if (posts.length === 0) {
        throw new ApiError(404, 'POST_NOT_FOUND', '게시글을 찾을 수 없습니다.');
      }
      const post = posts[0];
      const viewers = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      const viewerDepartmentId = viewers.length > 0 ? viewers[0].departmentId : null;
      // 가정: 부서 공개는 작성자와 같은 부서, 개인 공개는 작성자 본인만 열람 (대상 지정 컬럼이 스키마에 없음)
      const isAuthor = String(post.authorId) === String(user.id);
      let allowed = false;
      if (post.visibilityScope === 'ALL') {
        allowed = true;
      } else if (isAuthor) {
        allowed = true;
      } else if (post.visibilityScope === 'DEPARTMENT') {
        allowed =
          viewerDepartmentId !== null &&
          viewerDepartmentId !== undefined &&
          post.authorDepartmentId !== null &&
          String(viewerDepartmentId) === String(post.authorDepartmentId);
      }
      if (!allowed) {
        throw new ApiError(422, 'POST_ACCESS_DENIED', '열람 권한이 없는 게시물입니다.');
      }
      const attachments = await db.query(
        'SELECT attachment_id AS "attachmentId", file_name AS "fileName", file_ext AS "fileExt", file_size AS "fileSize" FROM attachment WHERE owner_type = :ownerType AND owner_id = CAST(:postId AS bigint) ORDER BY attachment_id',
        { ownerType: ATTACHMENT_OWNER_TYPE, postId },
      );
      return {
        postId: post.postId,
        title: post.title,
        authorId: post.authorId,
        content: post.content,
        visibilityScope: post.visibilityScope,
        attachments,
      };
    });
  }
}

