import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  TextInput,
  Select,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

const SCOPE_LABEL: Record<string, string> = {
  ALL: '전체',
  DEPARTMENT: '부서',
  INDIVIDUAL: '개인',
};

const TYPE_LABEL: Record<string, string> = {
  NOTICE: '공지',
  POST: '게시글',
};

function PostDetail({ role, postId, onClose }: { role: string; postId: number; onClose: () => void }) {
  const detail = useData<Row>(() => call('GET', '/posts/' + postId, role), [postId]);
  const post = detail.data;
  const attachments = (post && Array.isArray(post.attachments) ? post.attachments : []) as Row[];
  return (
    <Drawer title="게시글 상세" onClose={onClose}>
      {detail.loading && <p>불러오는 중입니다.</p>}
      {detail.error && <ErrorText text={detail.error} />}
      {post && (
        <Pairs
          items={[
            ['제목', String(post.title ?? '')],
            ['작성자', <RefName table="employee" role={role} value={post.authorId} />],
            ['공개범위', SCOPE_LABEL[String(post.visibilityScope)] ?? String(post.visibilityScope ?? '')],
            ['내용', <div style={{ whiteSpace: 'pre-wrap' }}>{String(post.content ?? '')}</div>],
            [
              '첨부파일 목록',
              attachments.length === 0 ? (
                '첨부파일이 없습니다.'
              ) : (
                <ul>
                  {attachments.map((a) => (
                    <li key={String(a.attachmentId)}>
                      {String(a.fileName ?? '')} (<Num value={a.fileSize} />B)
                    </li>
                  ))}
                </ul>
              ),
            ],
          ]}
        />
      )}
    </Drawer>
  );
}

export default function FnSfr04004Page({ role, notify }: PageProps) {
  const [category, setCategory] = useState('');
  const [postType, setPostType] = useState('');
  const [keyword, setKeyword] = useState('');
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/posts', role, undefined, { ...query, page, size: SIZE }),
    [role, query, page],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const noticeCount = rows.filter((r) => r.postType === 'NOTICE').length;

  const search = () => {
    setPage(0);
    setQuery({ category, postType, keyword });
  };

  const reset = () => {
    setCategory('');
    setPostType('');
    setKeyword('');
    setPage(0);
    setQuery({});
  };

  const columns: Column[] = [
    {
      key: 'postType',
      label: '구분',
      render: (r) => <Badge value={TYPE_LABEL[String(r.postType)] ?? String(r.postType ?? '')} />,
    },
    { key: 'category', label: '분류' },
    { key: 'title', label: '제목' },
    {
      key: 'authorId',
      label: '작성자',
      render: (r) => <RefName table="employee" role={role} value={r.authorId} />,
    },
    {
      key: 'createdAt',
      label: '생성 일시',
      render: (r) => <DateText value={r.createdAt} time />,
    },
    {
      key: 'pinStartDate',
      label: '상단 고정 시작일',
      render: (r) => <DateText value={r.pinStartDate} />,
    },
    {
      key: 'pinEndDate',
      label: '상단 고정 종료일',
      render: (r) => <DateText value={r.pinEndDate} />,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['전체 게시글', <Num value={total} />],
            ['현재 쪽 공지', <Num value={noticeCount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>최근 공지·게시글</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="구분">
            <Select
              value={postType}
              onChange={setPostType}
              options={[
                ['NOTICE', '공지'],
                ['POST', '게시글'],
              ]}
              placeholder="전체"
            />
          </Field>
          <Field label="분류">
            <TextInput value={category} onChange={setCategory} />
          </Field>
          <Field label="제목 등 검색어">
            <TextInput value={keyword} onChange={setKeyword} />
          </Field>
        </Filters>
        <Band total={total} />
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setSelected(Number(r.postId))}
          empty="조회된 게시글이 없습니다."
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selected !== null && (
        <PostDetail role={role} postId={selected} onClose={() => setSelected(null)} />
      )}
    </div>
  );
}
